                else if (e === 'renewfixed') { B.push({ n: 'esp', ha: C.ESP_HA, s: 1, c: 1, rent: C.RENT[3], black: false }); }
                else if (e === 'renewshare') { B.push({ n: 'esp', ha: C.ESP_HA, s: tenant, c: 1, rent: 0, black: false }); }
            }
            var t, ha;
            if (q === 1) {
                ha = C.SCALE[r1.scale];
                if (ha) { B.push({ n: 'third', ha: ha, s: 1, c: 1, rent: C.RENT[0], black: false }); }
            } else if (q === 2 || q === 3) {
                t = r2.third;
                if (t === 'fixed400') { B.push({ n: 'third', ha: 400, s: 1, c: 1, rent: C.RENT[1], black: false }); }
                else if (t === 'fixed800') { B.push({ n: 'third', ha: 800, s: 1, c: 1, rent: C.RENT[1], black: false }); }
                else if (t === 'share800') { B.push({ n: 'third', ha: 800, s: tenant, c: 1, rent: 0, black: false }); }
                else if (t === 'black800') { B.push({ n: 'third', ha: 800, s: 1, c: 1, rent: C.RENT[1] * (1 - C.BLACK_DISC), black: true }); }
            } else {
                t = r4.third;
                if (t === '400' || t === '800') { B.push({ n: 'third', ha: Number(t), s: 1, c: 1, rent: C.RENT[3], black: false }); }
                else if (t === 'black400') { B.push({ n: 'third', ha: 400, s: 1, c: 1, rent: C.RENT[3] * (1 - C.BLACK_DISC), black: true }); }
            }
            if (r3) {
                if (r3.land === 'cash' || r3.land === 'mortgage') { B.push({ n: 'd100', ha: C.D100_HA, s: 1, c: 1, rent: 0, black: false }); }
                if (r3.jv === 'share50') { B.push({ n: 'jv', ha: C.JV_HA, s: 0.5, c: 0.5, rent: 0, black: false }); }
                else if (r3.jv === 'leaseall') { B.push({ n: 'jv', ha: C.JV_HA, s: 1, c: 1, rent: C.RENT[q - 1], black: false }); }
            }
            return B;
        }

        _opHa(dec, q) {
            var B = this._blocks(dec, q);
            var tot = 0;
            var i;
            for (i = 0; i < B.length; i++) { tot += B[i].ha; }
            if (q >= 3 && dec.round3.jv === 'fee') { tot += C.JV_HA; }
            return tot;
        }

        _policy(dec, q) {
            if (q <= 2) { return dec.round1.insure; }
            if (q === 4) { return dec.round4.insure; }
            return 'none';
        }

        _campaign(dec, q, cashOpen) {
            var r1 = dec.round1;
            var r2 = (q >= 2) ? dec.round2 : null;
            var r3 = (q >= 3) ? dec.round3 : null;
            var r4 = (q >= 4) ? dec.round4 : null;
            var rh = this._revHa(q);
            var rev = rh.rev;
            var D = C.D - ((r2 && r2.cash === 'combine') ? C.COMBINE_SAVE : 0);
            var B = this._blocks(dec, q);
            var pol = this._policy(dec, q);
            var fund = r2 ? r2.fund : 'overdraft';
            var revenue = 0, direct = 0, rents = 0, prem = 0, payout = 0, blackHa = 0, opHa = 0, jvIncome = 0, fullRev = 0;
            var multiPay = Math.max(0, C.MULTI_TRIGGER * C.Y_EXP - rh.yld) * C.PRICE[q - 1];
            var i, b, rv, dc, rt;
            for (i = 0; i < B.length; i++) {
                b = B[i];
                opHa += b.ha;
                rv = b.s * rev * b.ha;
                dc = b.c * D * b.ha;
                rt = b.rent * b.ha;
                revenue += rv;
                direct += dc;
                rents += rt;
                fullRev += b.ha * rev;
                if (b.black) { blackHa += b.ha; }
                prem += b.s * C.PREM[pol] * b.ha;
                if (pol === 'multi') { payout += b.s * multiPay * b.ha; }
                else if (pol === 'hail') { payout += b.s * rh.hailv * b.ha; }
                if (b.n === 'jv') { jvIncome = rv - dc - rt; }
            }
            var fee = 0;
            if (r3 && r3.jv === 'fee') {
                opHa += C.JV_HA;
                fee = C.JV_HA * (C.FEE_HA + C.FEE_PROFIT * Math.max(0, rev - D));
                jvIncome = fee;
            }
            var excessHa = Math.max(0, opHa - C.CAPACITY);
            var surcharge = C.SURCHARGE * excessHa;
            var avgShare = fullRev > 0 ? revenue / fullRev : 1;
            var timely = C.TIMELY * rev * excessHa * avgShare;
            var canje = (fund === 'canje' && q >= 2);
            var canjePrem = canje ? C.CANJE_PREM * C.INPUT_SHARE * direct : 0;
            var deferred = canje ? C.INPUT_SHARE * direct : 0;
            var lineFee = (fund === 'line' && q >= 2) ? C.LINE_FEE : 0;
            var line = (fund === 'line' && q >= 2) ? C.LINE_EXT : C.LINE0;
            var capex = 0, debt = 0;
            if (r1.tenure === 'buy') {
                debt += C.LTV * C.ESP_PRICE * C.ESP_HA;
                if (q === 1) { capex += (1 - C.LTV + C.TX) * C.ESP_PRICE * C.ESP_HA; }
            } else if (q === 4 && r4.esp === 'buy') {
                debt += C.LTV * C.ESP_PRICE4 * C.ESP_HA;
                capex += (1 - C.LTV + C.TX) * C.ESP_PRICE4 * C.ESP_HA;
            }
            if (r3 && r3.land === 'cash') {
                if (q === 3) { capex += (1 + C.TX) * C.D100_PRICE * C.D100_HA; }
            } else if (r3 && r3.land === 'mortgage') {
                debt += C.LTV * C.D100_PRICE * C.D100_HA;
                if (q === 3) { capex += (1 - C.LTV + C.TX) * C.D100_PRICE * C.D100_HA; }
            }
            var mortInt = C.MORT_RATE * debt;
            var combine = (q === 2 && r2 && r2.cash === 'combine') ? C.COMBINE : 0;
            var dividend = (q === 2 && r2 && r2.cash === 'dividend') ? C.DIVIDEND : 0;
            var clauseCost = (r3 && r3.jv !== 'none' && q === 3) ? C.CLAUSE_COST[r3.clause] : 0;
            var pre = (direct - deferred) + rents + C.OVERHEAD + prem + surcharge + lineFee + clauseCost + capex + combine + dividend;
            var trough = cashOpen - pre;
            var odInt = C.OD_RATE * Math.max(0, -trough);
            var resultEx = revenue - timely + payout + fee - direct - rents - C.OVERHEAD - prem - surcharge - canjePrem - lineFee - clauseCost - mortInt - odInt;
            return {
                q: q, opHa: opHa, excessHa: excessHa, yld: rh.yld, revenue: revenue, payout: payout, fee: fee, direct: direct, rents: rents,
                prem: prem, surcharge: surcharge, timely: timely, canjePrem: canjePrem, lineFee: lineFee, line: line, mortInt: mortInt,
                odInt: odInt, capex: capex, combine: combine, dividend: dividend, clauseCost: clauseCost, trough: trough, debt: debt,
                blackHa: blackHa, jvIncome: jvIncome, resultEx: resultEx
            };
        }

        _rubric(dec, r) {
            var P = C.PTS;
            var d, sc, cl, es, th;
            if (r === 1) {
                d = dec.round1;
                if (d.scale === '0') { sc = P.scale1.zero; }
                else { sc = (this._opHa(dec, 1) <= C.CAPACITY) ? P.scale1.within : P.scale1.over; }
                return P.tenure1[d.tenure] + sc + P.insure1[d.insure];
            }
            if (r === 2) {
                d = dec.round2;
                return P.third2[d.third] + P.cash2[d.cash] + P.fund2[d.fund];
            }
            if (r === 3) {
                d = dec.round3;
                cl = (d.jv === 'none') ? C.CLAUSE_NEUTRAL : P.clause3[d.clause];
                return P.jv3[d.jv] + cl + P.land3[d.land];
            }
            d = dec.round4;
            es = (dec.round1.tenure === 'buy') ? C.ESP_NEUTRAL : P.esp4[d.esp];
            if (d.third === '0') { th = P.third4.zero; }
            else if (d.third === 'black400') { th = P.third4.black400; }
            else { th = (this._opHa(dec, 4) <= C.CAPACITY) ? P.third4.within : P.third4.over; }
            return es + th + P.insure4[d.insure];
        }

        _netWorth(dec, q, cash, debt, dividends) {
            var nw = cash - C.CASH0 + dividends - debt;
            var r2 = dec.round2 || {};
            var r3 = dec.round3 || {};
            var r4 = dec.round4 || {};
            var lv = C.LAND_V[q - 1];
            if (dec.round1.tenure === 'buy' || (q === 4 && r4.esp === 'buy')) { nw += C.ESP_HA * lv; }
            if (q >= 3 && (r3.land === 'cash' || r3.land === 'mortgage')) { nw += C.D100_HA * lv; }
            if (q >= 2 && r2.cash === 'combine') { nw += C.COMBINE * C.COMBINE_RES; }
            return nw;
        }

        _verdict(dec, r, liqExcess, black) {
            if (r === 1) {
                var r1 = dec.round1;
                if (r1.tenure === 'buy') { return 'buytop'; }
                if (r1.insure !== 'multi') { return 'uninsured'; }
                if (r1.tenure === 'none' && r1.scale === '0') { return 'idle'; }
                return 'ok';
            }
            if (r === 2) {
                var r2 = dec.round2;
                if (r2.third === 'black800') { return 'black'; }
                if (r2.third === 'fixed400' || r2.third === 'fixed800') { return 'boomrent'; }
                if (r2.cash !== 'reserve') { return 'drain'; }
                if (r2.fund === 'overdraft') { return 'noline'; }
                return 'ok';
            }
            if (r === 3) {
                var r3 = dec.round3;
                if (r3.jv === 'leaseall') { return 'allrisk'; }
                if (r3.jv !== 'none' && r3.clause === 'handshake') { return 'handshake'; }
                if (r3.land === 'mortgage') { return 'landdebt'; }
                return 'ok';
            }
            if (liqExcess > 0) { return 'squeeze'; }
            if (black > 0) { return 'black'; }
            if (dec.round4.insure !== 'hail') { return 'wrongcover'; }
            return 'ok';
        }

        _tier(score) {
            if (score >= 75) { return 'excellent'; }
            if (score >= 55) { return 'good'; }
            return 'beginner';
        }

        _liqCap(ds) {
            var ex = (ds && ds.liqExcess) || 0;
            return Math.max(C.CAP_FLOOR, C.LIQ_CAP - ex / C.LIQ_STEP);
        }

        _blackCap(ds) {
            var bh = (ds && ds.blackHa) || 0;
            return Math.max(C.CAP_FLOOR, C.BLACK_CAP - C.BLACK_STEP * bh);
        }

        _cap(ds) {
            var cap = 100;
            if (((ds && ds.blackHa) || 0) > 0) { cap = Math.min(cap, this._blackCap(ds)); }
            if (((ds && ds.liqExcess) || 0) > 0) { cap = Math.min(cap, this._liqCap(ds)); }
            return cap;
        }

        _total(ds) {
            var rounds = (ds && ds.rounds) || [];
            var total = 0;
            var i;
            for (i = 0; i < rounds.length; i++) { total += rounds[i].pts; }
            return total;
        }

        _capKey(ds) {
            var total = this._total(ds);
            var cap = this._cap(ds);
            if (total <= cap) { return null; }
            if (((ds && ds.liqExcess) || 0) > 0 && cap === this._liqCap(ds)) { return 'cap_liq'; }
            return 'cap_black';
        }

        _composite(ds) {
            var total = Math.min(this._cap(ds), this._total(ds));
            return Math.max(0, Math.min(100, Math.round(total)));
        }

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.performance.overallScore', function(v) { return (typeof v === 'number') ? String(v) : '0'; });
            uiManager.bind('resultDisplay', 'domainState', function(ds) {
                var cs = (ds && ds.campaigns) || [];
                return cs.length ? self._fmtUsd(cs[cs.length - 1].result) : '—';
            });
            uiManager.bind('cashDisplay', 'domainState', function(ds) {
                return self._fmtUsd((ds && typeof ds.cash === 'number') ? ds.cash : C.CASH0);
            });
            uiManager.bind('haDisplay', 'domainState', function(ds) {
                var cs = (ds && ds.campaigns) || [];
                return cs.length ? self._fmtInt(cs[cs.length - 1].opHa) : String(C.OWN_HA);
            });
            uiManager.bind('yieldDisplay', 'domainState', function(ds) {
                var cs = (ds && ds.campaigns) || [];
                return cs.length ? self._fmt2(cs[cs.length - 1].yld) : '—';
            });
            uiManager.bind('troughDisplay', 'domainState', function(ds) {
                var cs = (ds && ds.campaigns) || [];
                return cs.length ? self._fmtUsd(cs[cs.length - 1].trough) : '—';
            });
            uiManager.bind('nwDisplay', 'domainState', function(ds) {
                return (ds && typeof ds.netWorth === 'number') ? self._fmtUsd(ds.netWorth) : '—';
            });
        }

