            var t = this._t.bind(this);
            var sp = t('s_short');
            return {
                resultChart: {
                    type: 'bar',
                    data: {
                        labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
                        datasets: [{ label: t('chart_dataset'), data: [0, 0, 0, 0], backgroundColor: ['#3f5f2a', '#8a3b12', '#3f5f2a', '#3f5f2a'], borderWidth: 0 }]
                    },
                    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { ticks: { color: '#3b3a2c' } }, x: { ticks: { color: '#3b3a2c' } } } }
                }
            };
