        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var cs = ds.campaigns || [];
            var hist = ds.scoreHistory || [];
            var data = [0, 0, 0, 0];
            var sp = this._t('s_short');
            var i;
            for (i = 0; i < cs.length && i < 4; i++) { data[i] = Math.round(cs[i].result / 1000); }
            return {
                resultChart: {
                    labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
