                { key: 'results.cash', label: 'Closing cash', i18nKey: 'col_cash', formatter: function(v) { return self._fmtUsd(v); } },
                { key: 'results.hectares', label: 'Hectares farmed', i18nKey: 'col_ha' },
                { key: 'results.yieldTha', label: 'Yield', i18nKey: 'col_yield' },
