        getHint(state, results) {
            var ds = state.domainState || {};
            var r = (ds.rounds || [])[(results.period || 1) - 1];
            if (!r) { return null; }
            return this._t('hint_r' + r.period + '_' + r.verdictKey);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var ds = window.mySimulation.state.domainState;
            var cs = ds.campaigns || [];
            var hist = ds.scoreHistory || [];
            var dec = ds.dec || {};
            var composite = this._composite(ds);
            var performance = 'Beginner';
            if (composite >= 55) { performance = 'Good'; }
            if (composite >= 75) { performance = 'Excellent'; }
            var last = cs.length ? cs[cs.length - 1] : null;
            var insights = [];
            var r1 = dec.round1 || {};
            var r2 = dec.round2 || {};
            var r3 = dec.round3 || {};
            if (r1.tenure === 'buy') { insights.push(this._t('insight_tenure_buy')); }
            else if (r1.tenure === 'share') { insights.push(this._t('insight_tenure_share')); }
            else { insights.push(this._t('insight_tenure_other')); }
            insights.push((r2.third === 'fixed400' || r2.third === 'fixed800' || r2.third === 'black800') ? this._t('insight_drought_fixed') : this._t('insight_drought_ok'));
            insights.push((ds.liqExcess || 0) > 0 ? this._t('insight_liq_bad') : this._t('insight_liq_ok'));
            if ((ds.blackHa || 0) > 0) { insights.push(this._t('insight_black')); }
            if (r3.jv === 'none') { insights.push(this._t('insight_jv_none')); }
            else if (r3.jv === 'leaseall' || r3.clause === 'handshake') { insights.push(this._t('insight_jv_weak')); }
            else { insights.push(this._t('insight_jv_ok')); }
            insights.push(this._t('insight_next'));
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                cash: ds.cash,
                minTrough: ds.minTrough,
                netWorth: ds.netWorth,
                hectares: last ? last.opHa : C.OWN_HA,
                rounds: hist.length,
                performance: performance,
                performanceKey: performance.toLowerCase(),
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

